CREATE MATERIALIZED VIEW non_leaf_831 AS
SELECT n.id AS n_id, n.name AS n_name, n.imdb_index AS n_imdb_index, n.imdb_id AS n_imdb_id, n.gender AS n_gender, n.name_pcode_cf AS n_name_pcode_cf, n.name_pcode_nf AS n_name_pcode_nf, n.surname_pcode AS n_surname_pcode, n.md5sum AS n_md5sum, cn.id AS cn_id, cn.name AS cn_name, cn.country_code AS cn_country_code, cn.imdb_id AS cn_imdb_id, cn.name_pcode_nf AS cn_name_pcode_nf, cn.md5sum AS cn_md5sum, ct.id AS ct_id, ct.kind AS ct_kind, mc.id AS mc_id, mc.movie_id AS mc_movie_id, mc.company_id AS mc_company_id, mc.company_type_id AS mc_company_type_id, mc.note AS mc_note, it2.id AS it2_id, it2.info AS it2_info, pi.id AS pi_id, pi.person_id AS pi_person_id, pi.info_type_id AS pi_info_type_id, pi.info AS pi_info, pi.note AS pi_note, mi1.id AS mi1_id, mi1.movie_id AS mi1_movie_id, mi1.info_type_id AS mi1_info_type_id, mi1.info AS mi1_info, mi1.note AS mi1_note, ci.id AS ci_id, ci.person_id AS ci_person_id, ci.movie_id AS ci_movie_id, ci.person_role_id AS ci_person_role_id, ci.note AS ci_note, ci.nr_order AS ci_nr_order, ci.role_id AS ci_role_id, rt.id AS rt_id, rt.role AS rt_role
FROM name AS n, company_name AS cn, company_type AS ct, movie_companies AS mc, info_type AS it2, person_info AS pi, movie_info AS mi1, cast_info AS ci, role_type AS rt
WHERE n.id = ci.person_id AND cn.id = mc.company_id AND ct.id = mc.company_type_id AND mc.movie_id = ci.movie_id AND it2.id = 29 AND pi.person_id = ci.person_id AND pi.info ~~* '%wa%' AND pi.info_type_id = 29 AND mi1.movie_id = ci.movie_id AND mi1.info ~~* '%cub%' AND mi1.info_type_id = 8 AND ci.role_id = rt.id AND rt.role IN ('actor', 'cinematographer', 'composer', 'costume designer', 'producer');